$ES_RV_CARD = <<<'ESP66E'
<div class="rounded-2xl border border-slate-200/80 bg-white p-5 shadow-2xs"><div class="flex flex-wrap items-center justify-between gap-2 border-b border-slate-100 pb-3"><div><div class="text-sm font-black text-slate-900">{ES_NAME}</div>{ES_ORG_HTML}</div><div class="flex items-center gap-3"><div class="flex items-center gap-0.5" aria-label="{ES_ARIA}">{ES_STARS_SM}</div><span class="rounded-lg bg-slate-100 px-2.5 py-1 text-[10.5px] font-bold text-slate-500 tabular-nums">{ES_DATE}</span></div></div><p class="mt-3 text-[13px] leading-7 font-medium text-slate-600">{ES_TEXT}</p></div>
ESP66E;
