troke-linecap="round" stroke-linejoin="round" class="lucide lucide-star h-5 w-5 transition-transform group-hover/star:scale-110 fill-amber-400 text-amber-400" aria-hidden="true" data-review-star-svg="true"><path d="M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z"></path></svg><span class="text-[10px] font-black text-slate-500 tabular-nums">۵</span></button></div></div><div class="space-y-3"><div><label class="mb-1 block text-xs font-extrabold text-slate-700">نام و نام خانوادگی *</label><input type="text" required="" data-review-name="true" placeholder="مثلاً: مهندس رضا محمدی" class="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-xs font-semibold text-slate-800 placeholder:text-slate-400 focus:border-emerald-500 focus:outline-none" value=""/></div><div><label class="mb-1 block text-xs font-extrabold text-slate-700">مجموعه یا شهر (اختیاری)</label><input type="text" data-review-org="true" placeholder="مثلاً: شهرداری اصفهان / پیمانکار پروژه" class="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-xs font-semibold text-slate-800 placeholder:text-slate-400 focus:border-emerald-500 focus:outline-none" value=""/></div><div><label class="mb-1 block text-xs font-extrabold text-slate-700">متن دیدگاه شما *</label><textarea rows="3" required="" data-review-comment="true" placeholder="نظر خود را درباره کیفیت، نوردهی یا تجربه خرید این محصول بنویسید..." class="w-full rounded-xl border border-slate-200 bg-white p-3.5 text-xs leading-6 font-semibold text-slate-800 placeholder:text-slate-400 focus:border-emerald-500 focus:outline-none"></textarea></div><button type="submit" class="group relative inline-flex w-full items-center justify-center gap-2 rounded-2xl bg-gradient-to-l from-emerald-700 via-emerald-600 to-emerald-700 px-5 py-3.5 text-xs sm:text-sm font-black text-white shadow-[0_10px_24px_-6px_rgba(0,154,56,0.45)] ring-1 ring-emerald-500/40 transition-all duration-300 hover:-translate-y-0.5 hover:from-emerald-800 hover:via-emerald-700 hover:to-emerald-800 hover:shadow-[0_14px_30px_-6px_rgba(0,154,56,0.58)] active:translate-y-0 cursor-pointer"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-check h-4.5 w-4.5 shrink-0 transition-transform duration-300 group-hover:scale-110" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg><span>ثبت نظر و امتیاز</span></button><div data-review-success="true" class="hidden items-center gap-2 rounded-xl border border-emerald-200 bg-emerald-100/80 px-3.5 py-2.5 text-xs font-extrabold text-emerald-900"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-check h-4 w-4 shrink-0 text-emerald-700" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg><span>دیدگاه شما با موفقیت ثبت و به لیست نظرات اضافه شد.</span></div></div></form>
ESP66F;
$ES_RV_REGION = <<<'ESP66G'
<div data-prod-tab-panel="reviews" class="hidden"><div class="grid items-start gap-8 lg:grid-cols-12"><div class="space-y-5 lg:col-span-7">{ES_SUMMARY_HTML}<div data-reviews-list="true" class="space-y-3.5">{ES_ITEMS}</div></div><div class="lg:col-span-5">{ES_FORM_HTML}</div></div></div></div></div>
ESP66G;

/** ستاره‌های امتیاز — سایز sm (کارت) یا md (خلاصه)؛ پر تا n، خالی تا ۵ */
$es_stars = static function (int $n, string $cls): string {
    $full = '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-star ' . $cls . ' fill-amber-400 text-amber-400" aria-hidden="true"><path d="M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z"></path></svg>';
    $empty = '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-star ' . $cls . ' text-slate-200" aria-hidden="true"><path d="M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z"></path></svg>';
    return str_repeat($full, max(0, min(5, $n))) . str_repeat($empty, max(0, 5 - max(0, min(5, $n))));
};

// خلاصه امتیاز
$es_title = get_the_title($es_pid);
$es_avg_raw = trim((string) get_post_meta($es_pid, '_wc_average_rating', true));
$es_avg = $es_avg_raw !== '' ? rtrim(rtrim($es_avg_raw, '0'), '.') : '0';
$es_avg_int = (int) round((float) $es_avg);
$es_count = (int) get_comments_number($es_pid);
$es_summary = '<div class="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-slate-200/80 bg-slate-50/70 p-4 sm:px-5"><div class="flex items-center gap-3.5"><div class="grid h-13 w-13 place-items-center rounded-2xl bg-emerald-700 text-lg font-black text-white tabular-nums">' . es_fa_num($es_avg) . '</div><div><div class="flex items-center gap-1">' . $es_stars($es_avg_int, 'h-4 w-4') . '</div><div class="mt-1 text-xs font-bold text-slate-600">میانگین امتیاز خریداران برای ' . esc_html($es_title) . '</div></div></div><span data-reviews-count-badge="true" class="rounded-xl border border-emerald-200 bg-white px-3 py-1.5 text-xs font-extrabold text-emerald-800 tabular-nums">' . es_fa_num((string) $es_count) . ' دیدگاه ثبت‌شده</span></div>';

// لیست دیدگاه‌ها (تأییدشده)
$es_comments = get_comments(['post_id' => $es_pid, 'status' => 'approve', 'type' => 'comment']);
$es_items = '';
foreach ($es_comments as $es_c) {
    $es_cid = (int) ($es_c->comment_ID ?? 0);
    $es_rate = (int) get_comment_meta($es_cid, 'rating', true);
    $es_org = trim((string) get_comment_meta($es_cid, 'es_review_org', true));
    $es_org_html = $es_org !== '' ? '<div class="mt-0.5 text-[11px] font-bold text-emerald-700">' . esc_html($es_org) . '</div>' : '';
    $es_items .= strtr($ES_RV_CARD, [
        '{ES_NAME}'      => esc_html((string) ($es_c->comment_author ?? '')),
        '{ES_ORG_HTML}'  => $es_org_html,
        '{ES_ARIA}'      => esc_attr('امتیاز ' . es_fa_num((string) $es_rate) . ' از ۵'),
        '{ES_STARS_SM}'  => $es_stars($es_rate, 'h-3.5 w-3.5'),
        '{ES_DATE}'      => esc_html(es_fa_num((string) get_comment_date('Y/m/d', $es_c))),
        '{ES_TEXT}'      => esc_html((string) ($es_c->comment_content ?? '')),
    ]);
}

// فرم ثبت — مسیر استاندارد wp-comments-post.php + متای rating/es_review_org در Woo\Reviews
$es_form = strtr($ES_RV_FORM, [
    '{ES_FORM_ACTION}'   => esc_url(home_url('/wp-comments-post.php')),
    '{ES_POST_ID_HIDDEN}' => '<input type="hidden" name="comment_post_ID" value="' . esc_attr((string) $es_pid) . '"/>',
]);

echo strtr($ES_RV_REGION, [
    '{ES_SUMMARY_HTML}' => $es_summary,
    '{ES_ITEMS}'        => $es_items,
    '{ES_FORM_HTML}'    => $es_form,
]);
